@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{let form;const modal=new bootstrap.Modal('#confirmAction');document.querySelectorAll('[data-confirm-form]').forEach(item=>item.addEventListener('submit',event=>{if(item.dataset.confirmed)return;event.preventDefault();form=item;modal.show()}));document.getElementById('confirm-submit').addEventListener('click',()=>{form.dataset.confirmed='1';form.requestSubmit()})});</script>@endpush
